components.css:
.ds-btn-primary {
  background: var(--rail);
  color: var(--rail-ink);
  border: 1px solid var(--rail);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
  border-radius: 2px;
  padding: 0.5rem 0.85rem;
  cursor: pointer;
}
.ds-btn-primary:hover {
  background: var(--rail-deep);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.ds-btn-primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ds-btn-secondary {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--ink);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
  border-radius: 2px;
  padding: 0.5rem 0.85rem;
  cursor: pointer;
}
.ds-btn-secondary:hover {
  background: var(--slip);
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.ds-btn-secondary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ds-label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  color: var(--muted);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 0.92rem;
  line-height: 1.45;
}
.ds-field {
  background: var(--slip);
  color: var(--ink);
  border: 1px solid var(--muted);
  border-radius: 2px;
  padding: 0.45rem 0.55rem;
  min-width: 12rem;
  caret-color: var(--rail);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
}
.ds-field::placeholder {
  color: var(--muted);
}
.ds-field:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

.ds-rail {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  width: 15.5rem;
  padding: 1.25rem 0.75rem 2rem;
  background: var(--rail);
  color: var(--rail-ink);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
}
.ds-brand, .ds-nav-link, .ds-nav-current {
  color: var(--rail-ink);
  text-decoration: none;
}
.ds-brand {
  display: flex;
  gap: 0.65rem;
  align-items: center;
  padding: 0.35rem 0.7rem 1.1rem;
}
.ds-brand strong, .ds-brand-sub {
  display: block;
}
.ds-brand strong {
  font-size: 0.98rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.ds-brand-sub {
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.85rem;
}
.ds-mark {
  width: 1.75rem;
  height: 1.75rem;
  flex: none;
}
.ds-nav-link, .ds-nav-current {
  padding: 0.45rem 0.7rem;
  border-radius: 2px;
}
.ds-nav-current {
  background: var(--rail-ink);
  color: var(--rail);
}
.ds-nav-link:hover {
  background: rgba(255, 246, 246, 0.14);
}
.ds-nav-current:hover {
  background: var(--rail-ink);
  color: var(--rail-deep);
}
.ds-brand:focus-visible, .ds-nav-link:focus-visible, .ds-nav-current:focus-visible {
  outline: 2px solid var(--rail-ink);
  outline-offset: 2px;
}

.ds-stamp-dashed {
  border: 1px solid var(--stamp);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 6.5rem;
  border-color: var(--stamp);
  color: var(--stamp);
  background: transparent;
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 999px;
  line-height: 1.35;

  padding: 0.05rem 0.7rem 0.1rem;
  border-style: dashed;
}

.ds-stamp-solid {
  border: 1px solid var(--stamp);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 6.5rem;
  border-color: var(--stamp);
  color: var(--stamp);
  background: transparent;
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 999px;
  line-height: 1.35;

  padding: 0.05rem 0.7rem 0.1rem;
  border-style: solid;
}

.ds-stamp-double {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 6.5rem;
  padding: 0.08rem 0.7rem;
  border: 4px double var(--stamp);
  color: var(--stamp);
  background: transparent;
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 999px;
  line-height: 1.35;
}

.ds-ledger {
  overflow-x: auto;
  background: var(--slip);
  color: var(--ink);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  font-family: Barlow, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
}
.ds-ledger table {
  width: 100%;
  border-collapse: collapse;
  min-width: 52rem;
}
.ds-ledger th, .ds-ledger td {
  text-align: left;
  vertical-align: baseline;
  padding: 0.7rem 0.75rem;
  border-bottom: 1px solid var(--line);
}
.ds-ledger th {
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--muted);
}
.ds-ledger .ds-num {
  text-align: right;
}
.ds-ledger-title {
  display: block;
  font-weight: 600;
}
.ds-ledger-meta {
  display: block;
  color: var(--muted);
  font-size: 0.88rem;
  margin-top: 0.15rem;
}
.ds-ledger-figure {
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 600;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.ds-ledger .ds-num .ds-ledger-figure {
  display: block;
}
.ds-ledger-diff .ds-ledger-stamp, .ds-ledger-diff .ds-ledger-figure {
  display: inline-block;
  vertical-align: baseline;
}
.ds-ledger-diff .ds-ledger-figure {
  margin-left: 0.45rem;
}
.ds-ledger-stamp {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 6.5rem;
  padding: 0.08rem 0.7rem;
  border: 4px double var(--stamp);
  color: var(--stamp);
  background: transparent;
  font-family: "Barlow Condensed", Barlow, sans-serif;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 999px;
  line-height: 1.35;
}
